def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        if hp <= 2 or no_water >= 1:
            return max(0.0, min(budget, DAILY_SALARY * 0.75))
        return max(0.0, min(budget, DAILY_SALARY * 0.25))

    opp_signals = []
    urgent_count = 0
    rich_urgent_bids = []
    all_prev_bids = []

    for oid, opp in alive:
        prev = opp.get('previous_trace', {}) or {}
        prev_bid = prev.get('bid')
        if prev_bid is not None:
            try:
                prev_bid = float(prev_bid)
                all_prev_bids.append(prev_bid)
            except Exception:
                prev_bid = None

        urgency = 0.0
        if opp.get('hp', 10) <= 3:
            urgency += 1.2
        elif opp.get('hp', 10) <= 5:
            urgency += 0.7
        if opp.get('no_water_days', 0) >= 2:
            urgency += 1.2
        elif opp.get('no_water_days', 0) >= 1:
            urgency += 0.6
        if opp.get('budget', 0) >= 200:
            urgency += 0.4
        elif opp.get('budget', 0) <= 60:
            urgency -= 0.3
        if prev_bid is not None:
            if prev_bid >= 140:
                urgency += 0.8
            elif prev_bid >= 90:
                urgency += 0.4
            elif prev_bid <= 40:
                urgency -= 0.2

        if urgency >= 1.2:
            urgent_count += 1
            if prev_bid is not None:
                rich_urgent_bids.append(prev_bid)

        opp_signals.append((urgency, prev_bid, oid, opp))

    opp_signals.sort(key=lambda x: x[0], reverse=True)

    supply_tightness = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if supply_tightness < 0:
        supply_tightness = 0.0
    if supply_tightness > 1:
        supply_tightness = 1.0

    my_urgency = 0.0
    if hp <= 2:
        my_urgency += 1.8
    elif hp <= 4:
        my_urgency += 1.0
    elif hp <= 6:
        my_urgency += 0.4
    if no_water >= 2:
        my_urgency += 1.6
    elif no_water >= 1:
        my_urgency += 0.8
    my_urgency += 0.7 * supply_tightness
    if day >= 8:
        my_urgency += 0.2

    strongest_prev = 0.0
    if rich_urgent_bids:
        strongest_prev = max(rich_urgent_bids)
    elif all_prev_bids:
        strongest_prev = max(all_prev_bids)

    if my_urgency >= 2.6:
        base = max(DAILY_SALARY * 0.95, strongest_prev + 3.0)
    elif my_urgency >= 1.6:
        base = max(DAILY_SALARY * 0.72, strongest_prev + 2.0 if strongest_prev > 0 else DAILY_SALARY * 0.72)
    elif supply >= 22:
        base = DAILY_SALARY * 0.26
    elif supply >= 19:
        base = DAILY_SALARY * 0.42
    else:
        if strongest_prev >= 150:
            base = DAILY_SALARY * 0.55
        elif strongest_prev >= 100:
            base = strongest_prev + 1.5
        elif strongest_prev > 0:
            base = max(DAILY_SALARY * 0.48, strongest_prev + 1.0)
        else:
            base = DAILY_SALARY * 0.5

    if urgent_count >= 2 and supply <= 18:
        base += 6.0
    elif urgent_count == 0 and supply >= 20:
        base -= 6.0

    if budget < DAILY_SALARY:
        if my_urgency >= 2.0:
            base = min(base, budget)
        else:
            base = min(base, budget * 0.7)

    if hp >= 8 and no_water == 0 and supply >= 21:
        base = min(base, DAILY_SALARY * 0.35)

    bid = max(0.0, min(float(budget), float(base)))
    return bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    # Determine alive opponents
    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive'):
            alive_opps.append(o)

    # If no opponents alive, bid low
    if not alive_opps:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from immediate trace
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    # Compute a pressure signal from yesterday
    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    second_prev_bid = 0.0
    if len(yesterday_bids) >= 2:
        srt = sorted(yesterday_bids, reverse=True)
        second_prev_bid = srt[1]

    # Base bid: moderate to beat typical mid-pack without overpaying
    # If supply is high, competition likely increases but we can be cheaper.
    supply_ratio = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY + 1e-9)
    supply_ratio = max(0.0, min(1.0, supply_ratio))

    # Health pressure
    hp = float(my_status['hp'])
    no_water_days = int(my_status['no_water_days'])
    budget = float(my_status['budget'])

    # If we're in danger, bid aggressively; otherwise stay conservative.
    danger = 0
    if hp <= 2.0:
        danger = 2
    elif hp <= 4.0:
        danger = 1
    if no_water_days >= 2:
        danger = max(danger, 2)

    # Strategy: target around a fraction of highest yesterday bid, but cap by need.
    # If Cindy-like overbidding existed (very high highest_prev_bid), don't match it.
    target = 0.0
    if highest_prev_bid > 0:
        # Use second-highest as a safer anchor when available
        anchor = second_prev_bid if second_prev_bid > 0 else highest_prev_bid
        # In moderate competition, bid slightly above anchor; in high competition, bid a bit below highest.
        if danger == 0:
            target = min(highest_prev_bid * 0.85, anchor + DAILY_SALARY * (0.08 + 0.05 * (1.0 - supply_ratio)))
        elif danger == 1:
            target = min(highest_prev_bid * 0.95, anchor + DAILY_SALARY * (0.12 + 0.05 * (1.0 - supply_ratio)))
        else:
            target = min(highest_prev_bid * 1.05, anchor + DAILY_SALARY * (0.18 + 0.08 * (1.0 - supply_ratio)))
    else:
        # Fallback
        target = DAILY_SALARY * (0.45 + 0.15 * (1.0 - supply_ratio))

    # If supply is barely above requirement, we may need to secure water more reliably.
    if supply < (WATER_REQ * 1.2):
        target *= 1.12

    # Final clamp to budget and non-negative
    bid = max(0.0, min(budget, target))

    # Ensure we don't bid trivially low when danger is high
    if danger >= 2:
        bid = max(bid, min(budget, DAILY_SALARY * 0.75))
    elif danger == 1:
        bid = max(bid, min(budget, DAILY_SALARY * 0.55))

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    # If no opponents are alive, bid minimally to secure water.
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    # Calculate highest previous bid from active opponents
    highest_prev_bid = 0.0
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            highest_prev_bid = max(highest_prev_bid, prev['bid'])

    # --- Bidding Strategy ---

    # Emergency condition: If HP is 1 or 2, I must win to survive.
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.99)

    # Late game pressure: Last 3 days (Day 8, 9, 10)
    if day_context['day'] >= EPISODE_DAYS - 2:
        if my_status['hp'] <= 4: # Low-ish health in late game
            return min(my_status['budget'], DAILY_SALARY * 0.9)
        else: # Healthy enough for late game
            return min(my_status['budget'], DAILY_SALARY * 0.75)

    # Early to Mid-game (Day 1-7), not critically low HP
    # React to opponent's previous aggressive bidding
    if highest_prev_bid > DAILY_SALARY * 0.8: # Opponents are bidding high (above 120)
        if my_status['hp'] >= 8: # Very healthy, can afford to conserve or let others spend
            return min(my_status['budget'], DAILY_SALARY * 0.5)
        else: # HP is 3-7, need water soon, be aggressive
            return min(my_status['budget'], DAILY_SALARY * 0.85)
    else: # Opponents are not bidding super high (below or equal 120)
        if my_status['hp'] >= 8: # Very healthy, try to win cheaply or maintain pressure
            return min(my_status['budget'], max(DAILY_SALARY * 0.6, highest_prev_bid + 5.0))
        else: # HP is 3-7, need water soon, be more aggressive to win
            return min(my_status['budget'], max(DAILY_SALARY * 0.7, highest_prev_bid + 10.0))
